#!/bin/bash
set -euo pipefail
r=.cache/tasks/generational-barrier
e=evidence/research/generational-barrier
bash "$r/assert.sh" > "$r/assertions.log" 2>&1
rg -q '26 passing' "$r/quint-tests.log"
rg -q 'No violation found' "$r/quint-simulation.log"
! rg -q 'error:|sorryAx' "$r/lean-kernel.log" "$r/lean-scopes.log"
jq -e '.missingFiles==[] and .missingCustomIds==[] and .duplicateIds==[]' "$r/org-links.json" >/dev/null
jq -e '.exit==0 and ((.errors//[])|length)==0' "$r/native-metadata.json" >/dev/null
rg --files dev -g '*.sysml' -0 | xargs -0 openssl dgst -sha256 | LC_ALL=C sort > "$r/models-after.sha256"
cmp "$r/models-before.sha256" "$r/models-after.sha256"
sed -E 's/^[^(]+\((.*)\)= .*/\1/' "$r/entry-sources.sha256" | while IFS= read -r f; do openssl dgst -sha256 "$f"; done > "$r/preserved-after.sha256"
cmp "$r/entry-sources.sha256" "$r/preserved-after.sha256"
jq -r 'to_entries[]|[.key,.value]|@tsv' "$r/source-bindings.json" | while IFS=$'\t' read -r f expected; do test "$(openssl dgst -sha256 "$f"|awk '{print $NF}')" = "$expected"; done
jq -Rn '[inputs|capture("^[^(]+\\((?<key>.+)\\)= (?<value>[a-f0-9]{64})$")]|from_entries' "$r/models-after.sha256" > "$r/model-bindings.json"
jq --slurpfile m "$r/model-bindings.json" '.modelSourceBindings += $m[0]' dev/modeling/formal-bindings.json > "$r/formal-bindings-next.json"
cp "$r/formal-bindings-next.json" dev/modeling/formal-bindings.json
jq -e --slurpfile old "$r/entry-formal-bindings.json" 'del(.modelSourceBindings)==($old[0]|del(.modelSourceBindings))' dev/modeling/formal-bindings.json >/dev/null
jq -n --slurpfile p "$r/planner-input.json" --slurpfile a "$r/case-current.json" '[$p[0].components[]|.id as $id|{component:$id,needs:([$p[0].needs[]|select(.component==$id)]|length),qualifiedLocal:([$a[0].locallyChecked[]|select(.[1]==$id)]|length),frontier:[$a[0].componentFrontier[]|select(.[1]==$id)|.[2]],complete:([$a[0].componentReady[]|select(.[1]==$id)]|length>0)}]' > "$r/closure-matrix.json"
for s in $(jq -r '.cases[].id' "$r/scenarios.json"); do jq --arg case "$s" '{case:$case,componentReady:(.componentReady|map(.[1])|sort),qualifiedLocal:(.locallyChecked|length),frontier:(.componentFrontier|length),sourceRoutes:(.sourceRoute|length),runtimeAdmitted}' "$r/case-$s.json"; done | jq -s . > "$r/scenario-summary.json"
jq -n --slurpfile p "$r/planner-input.json" --slurpfile b "$r/source-bindings.json" '{qnt:{source:"models/gambit/generational_barrier.qnt",histories:26,testsLog:"quint-tests.log",typecheckLog:"typecheck-final.log",simulationLog:"quint-simulation.log",seed:17,samplesPerHistory:1,positiveSamples:100,maxSteps:80,invariant:"safe",exhaustive:false},lean:{source:"models/gambit/lean/GenerationalBarrier.lean",namedStatements:14,log:"lean-kernel.log",scopeProbe:"lean-scopes.log"},exactScopes:[$p[0].needs[]|select(.obligationId=="WB-H" or .obligationId=="WB-I")|{component,obligationId,subjectPath,subjectScope,digest}],wholeQntInvariantProvedInLean:false,wholeCollectorProof:false,cSourceSimulation:false,nativeRuntimeTest:false,livenessProved:false,typedSchemaSatisfactionClaimed:false}|.qnt.sourceSha256=$b[0][.qnt.source]|.lean.sourceSha256=$b[0][.lean.source]' > "$r/formal-checks.json"
jq -n '{primary:[{url:"https://mailman.iro.umontreal.ca/pipermail/gambit-list/2019-November/009234.html",scope:"Historical C/FFI assignment and generational barrier hazard"},{url:"https://anil.recoil.org/papers/2020-icfp-retropar.pdf",scope:"C API and sections 4.3-4.4; no benchmark transfer"},{url:"https://simonmar.github.io/bib/papers/parallel-gc.pdf",scope:"sections 2.1 and 4; remembered sources and forwarding"},{url:"https://xavierleroy.org/publi/concurrent-gc.pdf",scope:"Compile-time mutability and identity assumptions; no direct Scheme equivalence"},{url:"https://www.open-std.org/jtc1/sc22/wg14/www/docs/n1570.pdf",scope:"Historical C draft 5.1.2.4 and 7.17; no loaded-host conformance"}],sourceFamilies:10,externalCallerClosureProved:false,scope:"Current selected source hashes, not loaded profiles; local OCaml table growth and C memory assumptions separately reviewed"}' > "$r/primary-evidence.json"
quint --version > "$r/quint-version.txt"
sysml --version > "$r/sysml-version.txt" 2>&1
d2 --version > "$r/d2-version.txt" 2>&1
lean --version > "$r/lean-version.txt" 2>&1
rg --files --hidden --no-ignore "$r" -g '*.json' -g '*.ss' -g '*.scm' -g '*.qnt' -g '*.log' -g '*.sh' -g '*.el' -g '*.jq' -g '*.sha256' -g '*.txt' -g '*.tsv' -g 'probe.lean' -g '*.png' | while IFS= read -r f; do cp "$f" "$e/$(basename "$f")"; done
jq -n --slurpfile p "$r/planner-input.json" --slurpfile a "$r/case-current.json" --slurpfile f "$r/formal-checks.json" --slurpfile s "$r/scenario-summary.json" --slurpfile c "$r/closure-matrix.json" --slurpfile h "$r/source-bindings.json" --slurpfile o "$r/org-links.json" --slurpfile v "$r/native-values.json" --slurpfile old "$r/entry-traceability.json" --arg head "$(git rev-parse HEAD)" --arg time "$(date -u +%FT%TZ)" '{kind:"modern-c-generational-barrier-and-amplification-design",status:"barrier-card-reserve-kernel-checked-source-and-memory-open",recordedAt:$time,repositoryHead:$head,authority:{policy:"dev/modeling/models/sysml/assurance-routing.sysml",barrier:"dev/architecture/runtime/gc/models/sysml/generational-barrier.sysml",generational:"dev/architecture/runtime/gc/models/sysml/generational-admission.sysml",inference:"dev/modeling/ascent/assurance-planner.ss"},inputIdentity:{modelBundleSha256:$p[0].bundleHash,nativeOutputSha256:$p[0].nativeHash,dslSha256:$p[0].dslHash},sourceBindings:$h[0],structure:{nativeSysmlFiles:43,nativeEvaluatedScalars:($v[0]|length),components:8,needs:66,directPrerequisites:159,sharedContracts:8,sourceRoutes:24,sourceWriterFamilies:10,amplificationCases:6,typedTargetSchemas:3,typedTargetLaws:3,nativeMetadataAuthority:true,satisfactionClaimed:false},closure:{currentQualifiedLocalSlices:26,inheritedUnchangedSlices:24,currentSourceSimulationOpen:29,currentPlatformOpen:11,currentCompleteComponents:0,legacyGlobalObligationLedgerReclassified:false},formal:$f[0],reasoning:{current:$a[0],scenarios:$s[0],scenarioCases:13,selectedHypotheses:1,retainedTaskHypotheses:$a[0].retainedTaskHypotheses,supportObservations:0,exactRequiredRowsChecked:66,exactSourceRoutesChecked:24,allNativeDirectEdgesRetained:159,parserLimitsRaised:false},componentClosure:$c[0],org:{missingFiles:$o[0].missingFiles,missingCustomIds:$o[0].missingCustomIds,duplicateIds:$o[0].duplicateIds,babelExecuted:false},predecessor:{receipt:$old[0].checks.path,sha256:$old[0].checks.sha256,rerun:false,sourceDigestAndScopeChecked:true},views:{barrier:{nativeNodes:11,nativeConnections:13,arrowConnections:11,returnConnectionsInCaptions:2,visuallyReviewed:true},composed:{nodes:66,edges:159,topologyChecked:true}},execution:{sysmlNativeValidation:true,quintHistoryChecks:true,quintPositiveSimulation:true,leanKernelChecks:true,ascentQueries:true,runtimeImplementation:false,nativeRuntimeTesting:false,performanceValidation:false,commitOrPush:false},benefit:{capabilityAmplification:true,kind:"conditional-work-space-and-elision-equation",sufficientWorkBound:"A < (k-1)*M under one-major and matched-work premises",nativeSpeedupMeasured:false,personDaysUsed:false,modernCMandatory:true,zigIncrementalBenefitEstablished:false}}' > "$e/checks.json"
